    { const char * tb_v2368 = "// ---------- время и дата ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v2368; }
    { const char * tb_v2369 = "TB_API long long tb_unix_time(void) { return (long long)time(0); }\n"; *(const char * *)tb_grow(v_lines) = tb_v2369; }
    { const char * tb_v2370 = "TB_API const char *tb_date_now(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2370; }
    { const char * tb_v2371 = "    time_t t = time(0);\n"; *(const char * *)tb_grow(v_lines) = tb_v2371; }
    { const char * tb_v2372 = "    struct tm tmv;\n"; *(const char * *)tb_grow(v_lines) = tb_v2372; }
