    { const char * tb_v2378 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v2378; }
    { const char * tb_v2379 = "// ---------- http_get: страница из интернета через curl (есть на Mac и почти на любом Linux) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v2379; }
    { const char * tb_v2380 = "TB_API const char *tb_http_get(const char *url) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2380; }
    { const char * tb_v2381 = "    if (strncmp(url, \"http://\", 7) != 0 && strncmp(url, \"https://\", 8) != 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2381; }
    { const char * tb_v2382 = "        tb_err = tb_cat(\"адрес должен начинаться с http:// или https://: \", url);\n"; *(const char * *)tb_grow(v_lines) = tb_v2382; }
    { const char * tb_v2383 = "        return \"\";\n"; *(const char * *)tb_grow(v_lines) = tb_v2383; }
    { const char * tb_v2384 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2384; }
    { const char * tb_v2385 = "    // адрес — в одинарных кавычках для shell: ' внутри адреса пишется как '\\''\n"; *(const char * *)tb_grow(v_lines) = tb_v2385; }
    { const char * tb_v2386 = "    size_t n = strlen(url);\n"; *(const char * *)tb_grow(v_lines) = tb_v2386; }
    { const char * tb_v2387 = "    char *cmd = malloc(n * 4 + 80);\n"; *(const char * *)tb_grow(v_lines) = tb_v2387; }
    { const char * tb_v2388 = "    if (!cmd) { tb_err = \"не хватило памяти\"; return \"\"; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2388; }
    { const char * tb_v2389 = "#ifdef _WIN32\n"; *(const char * *)tb_grow(v_lines) = tb_v2389; }
    { const char * tb_v2390 = "    // curl.exe есть в Windows 10 и новее; адрес — в двойных кавычках для cmd.exe,\n"; *(const char * *)tb_grow(v_lines) = tb_v2390; }
    { const char * tb_v2391 = "    // (внутри кавычек & | < > ^ для cmd — простые знаки), а \" внутри адреса — как %22\n"; *(const char * *)tb_grow(v_lines) = tb_v2391; }
    { const char * tb_v2392 = "    size_t k = (size_t)sprintf(cmd, \"curl.exe -fsSL --max-time 30 \\\"\");\n"; *(const char * *)tb_grow(v_lines) = tb_v2392; }
    { const char * tb_v2393 = "    for (size_t i = 0; i < n; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2393; }
    { const char * tb_v2394 = "        unsigned char ch = (unsigned char)url[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v2394; }
    { const char * tb_v2395 = "        if (ch == '\"' || ch < 32) { sprintf(cmd + k, \"%%%02X\", ch); k += 3; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2395; }
    { const char * tb_v2396 = "        else cmd[k++] = url[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v2396; }
    { const char * tb_v2397 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2397; }
    { const char * tb_v2398 = "    strcpy(cmd + k, \"\\\" 2>NUL\");\n"; *(const char * *)tb_grow(v_lines) = tb_v2398; }
    { const char * tb_v2399 = "    FILE *p = popen(cmd, \"rb\");\n"; *(const char * *)tb_grow(v_lines) = tb_v2399; }
    { const char * tb_v2400 = "#else\n"; *(const char * *)tb_grow(v_lines) = tb_v2400; }
    { const char * tb_v2401 = "    size_t k = (size_t)sprintf(cmd, \"curl -fsSL --max-time 30 '\");\n"; *(const char * *)tb_grow(v_lines) = tb_v2401; }
    { const char * tb_v2402 = "    for (size_t i = 0; i < n; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2402; }
    { const char * tb_v2403 = "        if (url[i] == '\\'') { memcpy(cmd + k, \"'\\\\''\", 4); k += 4; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2403; }
    { const char * tb_v2404 = "        else cmd[k++] = url[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v2404; }
    { const char * tb_v2405 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2405; }
    { const char * tb_v2406 = "    strcpy(cmd + k, \"' 2>/dev/null\");\n"; *(const char * *)tb_grow(v_lines) = tb_v2406; }
    { const char * tb_v2407 = "    FILE *p = popen(cmd, \"r\");\n"; *(const char * *)tb_grow(v_lines) = tb_v2407; }
    { const char * tb_v2408 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v2408; }
    { const char * tb_v2409 = "    free(cmd);\n"; *(const char * *)tb_grow(v_lines) = tb_v2409; }
    { const char * tb_v2410 = "    if (p == 0) { tb_err = \"не могу запустить curl\"; return \"\"; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2410; }
    { const char * tb_v2411 = "    size_t cap = 4096, len = 0, got;\n"; *(const char * *)tb_grow(v_lines) = tb_v2411; }
    { const char * tb_v2412 = "    char *buf = tb_tmem(cap);\n"; *(const char * *)tb_grow(v_lines) = tb_v2412; }
    { const char * tb_v2413 = "    while ((got = fread(buf + len, 1, cap - len - 1, p)) > 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2413; }
    { const char * tb_v2414 = "        len += got;\n"; *(const char * *)tb_grow(v_lines) = tb_v2414; }
    { const char * tb_v2415 = "        if (len + 1 == cap) { buf = tb_resize(buf, cap, cap * 2); cap *= 2; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2415; }
    { const char * tb_v2416 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2416; }
    { const char * tb_v2417 = "    buf[len] = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2417; }
    { const char * tb_v2418 = "    if (pclose(p) != 0) { tb_err = tb_cat(\"не получилось скачать (нет сети, нет curl или сервер ответил ошибкой): \", url); return \"\"; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2418; }
    { const char * tb_v2419 = "    return buf;\n"; *(const char * *)tb_grow(v_lines) = tb_v2419; }
    { const char * tb_v2420 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2420; }
    { const char * tb_v2421 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v2421; }
    { const char * tb_v2422 = "// ---------- JSON: json_get(текст, \"users.0.name\") и json_text(текст) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v2422; }
    { const char * tb_v2423 = "TB_API const char *tb_js_ws(const char *p) { while (*p == ' ' || *p == '\\n' || *p == '\\r' || *p == '\\t') p++; return p; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2423; }
    { const char * tb_v2424 = "// пропустить одно значение; адрес после него или 0, если JSON сломан\n"; *(const char * *)tb_grow(v_lines) = tb_v2424; }
    { const char * tb_v2425 = "TB_API const char *tb_js_skip(const char *p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2425; }
    { const char * tb_v2426 = "    p = tb_js_ws(p);\n"; *(const char * *)tb_grow(v_lines) = tb_v2426; }
    { const char * tb_v2427 = "    if (*p == '\"') {\n"; *(const char * *)tb_grow(v_lines) = tb_v2427; }
    { const char * tb_v2428 = "        p++;\n"; *(const char * *)tb_grow(v_lines) = tb_v2428; }
    { const char * tb_v2429 = "        while (*p && *p != '\"') { if (*p == '\\\\' && p[1]) p++; p++; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2429; }
    { const char * tb_v2430 = "        return *p ? p + 1 : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2430; }
    { const char * tb_v2431 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2431; }
    { const char * tb_v2432 = "    if (*p == '{' || *p == '[') {\n"; *(const char * *)tb_grow(v_lines) = tb_v2432; }
    { const char * tb_v2433 = "        int d = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2433; }
    { const char * tb_v2434 = "        while (*p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2434; }
    { const char * tb_v2435 = "            if (*p == '\"') { p = tb_js_skip(p); if (!p) return 0; continue; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2435; }
    { const char * tb_v2436 = "            if (*p == '{' || *p == '[') d++;\n"; *(const char * *)tb_grow(v_lines) = tb_v2436; }
    { const char * tb_v2437 = "            else if (*p == '}' || *p == ']') { d--; if (d == 0) return p + 1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2437; }
    { const char * tb_v2438 = "            p++;\n"; *(const char * *)tb_grow(v_lines) = tb_v2438; }
    { const char * tb_v2439 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v2439; }
    { const char * tb_v2440 = "        return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2440; }
    { const char * tb_v2441 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2441; }
    { const char * tb_v2442 = "    const char *s = p;\n"; *(const char * *)tb_grow(v_lines) = tb_v2442; }
    { const char * tb_v2443 = "    while (*p && *p != ',' && *p != '}' && *p != ']' && *p != ' ' && *p != '\\n' && *p != '\\r' && *p != '\\t') p++;\n"; *(const char * *)tb_grow(v_lines) = tb_v2443; }
    { const char * tb_v2444 = "    return p == s ? 0 : p;\n"; *(const char * *)tb_grow(v_lines) = tb_v2444; }
    { const char * tb_v2445 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2445; }
    { const char * tb_v2446 = "TB_API int tb_js_hex(const char *p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2446; }
    { const char * tb_v2447 = "    int v = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2447; }
    { const char * tb_v2448 = "    for (int i = 0; i < 4; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2448; }
    { const char * tb_v2449 = "        char ch = p[i]; v <<= 4;\n"; *(const char * *)tb_grow(v_lines) = tb_v2449; }
    { const char * tb_v2450 = "        if (ch >= '0' && ch <= '9') v |= ch - '0';\n"; *(const char * *)tb_grow(v_lines) = tb_v2450; }
    { const char * tb_v2451 = "        else if (ch >= 'a' && ch <= 'f') v |= ch - 'a' + 10;\n"; *(const char * *)tb_grow(v_lines) = tb_v2451; }
    { const char * tb_v2452 = "        else if (ch >= 'A' && ch <= 'F') v |= ch - 'A' + 10;\n"; *(const char * *)tb_grow(v_lines) = tb_v2452; }
    { const char * tb_v2453 = "        else return -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v2453; }
    { const char * tb_v2454 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2454; }
    { const char * tb_v2455 = "    return v;\n"; *(const char * *)tb_grow(v_lines) = tb_v2455; }
    { const char * tb_v2456 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2456; }
    { const char * tb_v2457 = "// строка JSON (p смотрит на \") → обычный текст\n"; *(const char * *)tb_grow(v_lines) = tb_v2457; }
    { const char * tb_v2458 = "TB_API const char *tb_js_str(const char *p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2458; }
    { const char * tb_v2459 = "    const char *e = tb_js_skip(p);\n"; *(const char * *)tb_grow(v_lines) = tb_v2459; }
    { const char * tb_v2460 = "    if (!e) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2460; }
    { const char * tb_v2461 = "    char *out = tb_tmem(e - p + 1), *o = out;\n"; *(const char * *)tb_grow(v_lines) = tb_v2461; }
    { const char * tb_v2462 = "    p++;\n"; *(const char * *)tb_grow(v_lines) = tb_v2462; }
    { const char * tb_v2463 = "    while (*p != '\"') {\n"; *(const char * *)tb_grow(v_lines) = tb_v2463; }
    { const char * tb_v2464 = "        if (*p != '\\\\') { *o++ = *p++; continue; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2464; }
    { const char * tb_v2465 = "        p++;\n"; *(const char * *)tb_grow(v_lines) = tb_v2465; }
    { const char * tb_v2466 = "        char ch = *p++;\n"; *(const char * *)tb_grow(v_lines) = tb_v2466; }
    { const char * tb_v2467 = "        if (ch == 'n') *o++ = '\\n'; else if (ch == 't') *o++ = '\\t'; else if (ch == 'r') *o++ = '\\r';\n"; *(const char * *)tb_grow(v_lines) = tb_v2467; }
    { const char * tb_v2468 = "        else if (ch == 'b') *o++ = '\\b'; else if (ch == 'f') *o++ = '\\f';\n"; *(const char * *)tb_grow(v_lines) = tb_v2468; }
    { const char * tb_v2469 = "        else if (ch == 'u') {\n"; *(const char * *)tb_grow(v_lines) = tb_v2469; }
    { const char * tb_v2470 = "            int cp = tb_js_hex(p);\n"; *(const char * *)tb_grow(v_lines) = tb_v2470; }
    { const char * tb_v2471 = "            if (cp < 0) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2471; }
    { const char * tb_v2472 = "            p += 4;\n"; *(const char * *)tb_grow(v_lines) = tb_v2472; }
    { const char * tb_v2473 = "            if (cp >= 0xD800 && cp < 0xDC00 && p[0] == '\\\\' && p[1] == 'u') {\n"; *(const char * *)tb_grow(v_lines) = tb_v2473; }
    { const char * tb_v2474 = "                int lo = tb_js_hex(p + 2);\n"; *(const char * *)tb_grow(v_lines) = tb_v2474; }
    { const char * tb_v2475 = "                if (lo >= 0xDC00 && lo < 0xE000) { cp = 0x10000 + ((cp - 0xD800) << 10) + (lo - 0xDC00); p += 6; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2475; }
    { const char * tb_v2476 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v2476; }
    { const char * tb_v2477 = "            if (cp < 0x80) *o++ = (char)cp;\n"; *(const char * *)tb_grow(v_lines) = tb_v2477; }
    { const char * tb_v2478 = "            else if (cp < 0x800) { *o++ = (char)(0xC0 | (cp >> 6)); *o++ = (char)(0x80 | (cp & 63)); }\n"; *(const char * *)tb_grow(v_lines) = tb_v2478; }
    { const char * tb_v2479 = "            else if (cp < 0x10000) { *o++ = (char)(0xE0 | (cp >> 12)); *o++ = (char)(0x80 | ((cp >> 6) & 63)); *o++ = (char)(0x80 | (cp & 63)); }\n"; *(const char * *)tb_grow(v_lines) = tb_v2479; }
    { const char * tb_v2480 = "            else { *o++ = (char)(0xF0 | (cp >> 18)); *o++ = (char)(0x80 | ((cp >> 12) & 63)); *o++ = (char)(0x80 | ((cp >> 6) & 63)); *o++ = (char)(0x80 | (cp & 63)); }\n"; *(const char * *)tb_grow(v_lines) = tb_v2480; }
    { const char * tb_v2481 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v2481; }
    { const char * tb_v2482 = "        else *o++ = ch;\n"; *(const char * *)tb_grow(v_lines) = tb_v2482; }
    { const char * tb_v2483 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2483; }
    { const char * tb_v2484 = "    *o = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2484; }
