    { const char * tb_v5376 = "// Треугольник. Правило точек одно для процессора и видеокарты (кадры совпадают точка в точку):\n"; *(const char * *)tb_grow(v_lines) = tb_v5376; }
    { const char * tb_v5377 = "// точка (x, y) берётся по своему центру (x + 0.5, y + 0.5); углы обходятся так, что площадь > 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5377; }
    { const char * tb_v5378 = "// для каждой стороны a→b: e = (bx-ax)*(2y+1-2ay) - (by-ay)*(2x+1-2ax); точка внутри, если e > 0\n"; *(const char * *)tb_grow(v_lines) = tb_v5378; }
    { const char * tb_v5379 = "// для всех трёх, а если e == 0 — только на сторонах с by > ay или (by == ay и bx < ax).\n"; *(const char * *)tb_grow(v_lines) = tb_v5379; }
    { const char * tb_v5380 = "// Так у двух соседних треугольников общая сторона рисуется ровно один раз.\n"; *(const char * *)tb_grow(v_lines) = tb_v5380; }
    { const char * tb_v5381 = "// Углы дальше ±8192 точек: треугольник сначала обрезается рамкой вокруг окна (tb_poly_draw) —\n"; *(const char * *)tb_grow(v_lines) = tb_v5381; }
    { const char * tb_v5382 = "// тогда в шейдере (32-битные числа) ничего не переполняется.\n"; *(const char * *)tb_grow(v_lines) = tb_v5382; }
    { const char * tb_v5383 = "TB_INL long long tb_tri_clamp(long long v) { return v < -8192 ? -8192 : v > 8192 ? 8192 : v; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5383; }
    { const char * tb_v5384 = "// t = x1 y1 x2 y2 x3 y3; 0 — рисовать нечего (площадь 0 или целиком вне окна)\n"; *(const char * *)tb_grow(v_lines) = tb_v5384; }
    { const char * tb_v5385 = "TB_INL int tb_tri_prep(long long *t) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5385; }
    { const char * tb_v5386 = "    for (int i = 0; i < 6; i++) t[i] = tb_tri_clamp(t[i]);\n"; *(const char * *)tb_grow(v_lines) = tb_v5386; }
    { const char * tb_v5387 = "    long long a2 = (t[2] - t[0]) * (t[5] - t[1]) - (t[3] - t[1]) * (t[4] - t[0]);\n"; *(const char * *)tb_grow(v_lines) = tb_v5387; }
    { const char * tb_v5388 = "    if (a2 == 0) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5388; }
    { const char * tb_v5389 = "    if (a2 < 0) { long long x = t[2], y = t[3]; t[2] = t[4]; t[3] = t[5]; t[4] = x; t[5] = y; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5389; }
    { const char * tb_v5390 = "    long long x0 = t[0], x1 = t[0], y0 = t[1], y1 = t[1];\n"; *(const char * *)tb_grow(v_lines) = tb_v5390; }
    { const char * tb_v5391 = "    for (int i = 2; i < 6; i += 2) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5391; }
    { const char * tb_v5392 = "        if (t[i] < x0) x0 = t[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v5392; }
    { const char * tb_v5393 = "        if (t[i] > x1) x1 = t[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v5393; }
    { const char * tb_v5394 = "        if (t[i + 1] < y0) y0 = t[i + 1];\n"; *(const char * *)tb_grow(v_lines) = tb_v5394; }
    { const char * tb_v5395 = "        if (t[i + 1] > y1) y1 = t[i + 1];\n"; *(const char * *)tb_grow(v_lines) = tb_v5395; }
    { const char * tb_v5396 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v5396; }
    { const char * tb_v5397 = "    return !(x1 < 0 || y1 < 0 || x0 > tb_gw || y0 > tb_gh);\n"; *(const char * *)tb_grow(v_lines) = tb_v5397; }
    { const char * tb_v5398 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5398; }
    { const char * tb_v5399 = "TB_INL int tb_tri_edge(long long ax, long long ay, long long bx, long long by, long long x, long long y) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5399; }
    { const char * tb_v5400 = "    long long ex = bx - ax, ey = by - ay, e = ex * (2 * y + 1 - 2 * ay) - ey * (2 * x + 1 - 2 * ax);\n"; *(const char * *)tb_grow(v_lines) = tb_v5400; }
    { const char * tb_v5401 = "    return e > 0 || (e == 0 && (ey > 0 || (ey == 0 && ex < 0)));\n"; *(const char * *)tb_grow(v_lines) = tb_v5401; }
    { const char * tb_v5402 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5402; }
    { const char * tb_v5403 = "// глубина точки (x, y) по плоскости треугольника — так же, как в шейдере: 32-битные числа\n"; *(const char * *)tb_grow(v_lines) = tb_v5403; }
    { const char * tb_v5404 = "// без знака (переполнение по кругу), потом сдвиг; 0 — у самой камеры, 16777215 — далеко\n"; *(const char * *)tb_grow(v_lines) = tb_v5404; }
    { const char * tb_v5405 = "TB_INL uint32_t tb_tri3_depth(const uint32_t *pl, long long x, long long y) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5405; }
    { const char * tb_v5406 = "    uint32_t k = pl[2] + pl[0] * (uint32_t)(2 * x + 1) + pl[1] * (uint32_t)(2 * y + 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v5406; }
    { const char * tb_v5407 = "    int32_t d = (int32_t)k >> 6;\n"; *(const char * *)tb_grow(v_lines) = tb_v5407; }
    { const char * tb_v5408 = "    return d < 0 ? 0u : d > 16777215 ? 16777215u : (uint32_t)d;\n"; *(const char * *)tb_grow(v_lines) = tb_v5408; }
    { const char * tb_v5409 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5409; }
    { const char * tb_v5410 = "// треугольник с углами в пределах ±8192 (t меняется: порядок углов); pl — плоскость глубины (3D) или 0\n"; *(const char * *)tb_grow(v_lines) = tb_v5410; }
    { const char * tb_v5411 = "static void tb_tri_draw_i(long long *t, long long c, const uint32_t *pl) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5411; }
    { const char * tb_v5412 = "    if (!tb_tri_prep(t)) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v5412; }
    { const char * tb_v5413 = "    if (tb_gpu_on) { if (pl) tb_gpu_tri3(t, c, pl); else tb_gpu_triangle(t, c); }\n"; *(const char * *)tb_grow(v_lines) = tb_v5413; }
    { const char * tb_v5414 = "    if (TB_CPU_DRAW) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5414; }
    { const char * tb_v5415 = "        long long xa = t[0], xb = t[0], ya = t[1], yb = t[1];\n"; *(const char * *)tb_grow(v_lines) = tb_v5415; }
    { const char * tb_v5416 = "        for (int i = 2; i < 6; i += 2) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5416; }
    { const char * tb_v5417 = "            if (t[i] < xa) xa = t[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v5417; }
    { const char * tb_v5418 = "            if (t[i] > xb) xb = t[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v5418; }
    { const char * tb_v5419 = "            if (t[i + 1] < ya) ya = t[i + 1];\n"; *(const char * *)tb_grow(v_lines) = tb_v5419; }
    { const char * tb_v5420 = "            if (t[i + 1] > yb) yb = t[i + 1];\n"; *(const char * *)tb_grow(v_lines) = tb_v5420; }
    { const char * tb_v5421 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v5421; }
    { const char * tb_v5422 = "        if (xa < 0) xa = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5422; }
    { const char * tb_v5423 = "        if (ya < 0) ya = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5423; }
    { const char * tb_v5424 = "        if (xb > tb_gw - 1) xb = tb_gw - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v5424; }
    { const char * tb_v5425 = "        if (yb > tb_gh - 1) yb = tb_gh - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v5425; }
    { const char * tb_v5426 = "        for (long long y = ya; y <= yb; y++)\n"; *(const char * *)tb_grow(v_lines) = tb_v5426; }
    { const char * tb_v5427 = "            for (long long x = xa; x <= xb; x++)\n"; *(const char * *)tb_grow(v_lines) = tb_v5427; }
    { const char * tb_v5428 = "                if (tb_tri_edge(t[0], t[1], t[2], t[3], x, y) && tb_tri_edge(t[2], t[3], t[4], t[5], x, y) &&\n"; *(const char * *)tb_grow(v_lines) = tb_v5428; }
    { const char * tb_v5429 = "                    tb_tri_edge(t[4], t[5], t[0], t[1], x, y)) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5429; }
    { const char * tb_v5430 = "                    if (pl) {   // 3D: точка видна, если ближе того, что уже нарисовано\n"; *(const char * *)tb_grow(v_lines) = tb_v5430; }
    { const char * tb_v5431 = "                        uint32_t d = tb_tri3_depth(pl, x, y);\n"; *(const char * *)tb_grow(v_lines) = tb_v5431; }
    { const char * tb_v5432 = "                        if (d >= tb_zb[y * tb_gw + x]) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v5432; }
    { const char * tb_v5433 = "                        tb_zb[y * tb_gw + x] = d;\n"; *(const char * *)tb_grow(v_lines) = tb_v5433; }
    { const char * tb_v5434 = "                    }\n"; *(const char * *)tb_grow(v_lines) = tb_v5434; }
    { const char * tb_v5435 = "                    tb_px[y * tb_gw + x] = (uint32_t)c;\n"; *(const char * *)tb_grow(v_lines) = tb_v5435; }
    { const char * tb_v5436 = "                }\n"; *(const char * *)tb_grow(v_lines) = tb_v5436; }
    { const char * tb_v5437 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v5437; }
    { const char * tb_v5438 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5438; }
    { const char * tb_v5439 = "// многоугольник с углами-дробями (3D после проекции, огромные треугольники): обрезаем рамкой\n"; *(const char * *)tb_grow(v_lines) = tb_v5439; }
    { const char * tb_v5440 = "// вокруг окна (±2048 точек, но не дальше ±8192), углы округляем, режем веером из первого угла.\n"; *(const char * *)tb_grow(v_lines) = tb_v5440; }
    { const char * tb_v5441 = "// Общие углы округляются одинаково, поэтому соседние треугольники стыкуются без щелей\n"; *(const char * *)tb_grow(v_lines) = tb_v5441; }
