    { const char * tb_v5495 = "// текст: буква 8×16, size — во сколько раз крупнее\n"; *(const char * *)tb_grow(v_lines) = tb_v5495; }
    { const char * tb_v5496 = "TB_API void tb_draw_text(long long x, long long y, const char *s, long long size, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5496; }
    { const char * tb_v5497 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v5497; }
    { const char * tb_v5498 = "    if (size < 1) size = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v5498; }
    { const char * tb_v5499 = "    const unsigned char *p = (const unsigned char *)s;\n"; *(const char * *)tb_grow(v_lines) = tb_v5499; }
    { const char * tb_v5500 = "    long long cx = x;\n"; *(const char * *)tb_grow(v_lines) = tb_v5500; }
    { const char * tb_v5501 = "    while (*p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5501; }
    { const char * tb_v5502 = "        unsigned int u = *p++;\n"; *(const char * *)tb_grow(v_lines) = tb_v5502; }
    { const char * tb_v5503 = "        if (u >= 0x80) {   // UTF-8: собрать букву из 2–4 байт\n"; *(const char * *)tb_grow(v_lines) = tb_v5503; }
    { const char * tb_v5504 = "            int more = u >= 0xF0 ? 3 : u >= 0xE0 ? 2 : u >= 0xC0 ? 1 : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5504; }
    { const char * tb_v5505 = "            u &= 0x3F >> more;\n"; *(const char * *)tb_grow(v_lines) = tb_v5505; }
    { const char * tb_v5506 = "            while (more-- > 0 && (*p & 0xC0) == 0x80) u = (u << 6) | (*p++ & 0x3F);\n"; *(const char * *)tb_grow(v_lines) = tb_v5506; }
    { const char * tb_v5507 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v5507; }
    { const char * tb_v5508 = "        if (u == 0x2013 || u == 0x2014) u = '-';\n"; *(const char * *)tb_grow(v_lines) = tb_v5508; }
    { const char * tb_v5509 = "        if (u == 0xD7) u = 'x';   // × как x (размер окна 640×400)\n"; *(const char * *)tb_grow(v_lines) = tb_v5509; }
    { const char * tb_v5510 = "        if (u == 0xAB || u == 0xBB || u == 0x201C || u == 0x201D) u = '\"';\n"; *(const char * *)tb_grow(v_lines) = tb_v5510; }
    { const char * tb_v5511 = "        if (u == '\\n') { cx = x; y += 16 * size; continue; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5511; }
